/**
 * Payment state machine.
 *
 * The transition table is a direct encoding of docs/transitions.md.
 * DO NOT edit this file without explicit instruction from the human  -  propose changes in chat.
 *
 * applyEvent() is the single entry point. It:
 *   1. Looks up the cell for (currentState, eventType).
 *   2. Executes the cell's outcome.
 *   3. Returns a TransitionResult describing what happened.
 *
 * The runner owns retry counters and settle-window timing; the state machine
 * only acts on the event it receives  -  it does not schedule anything.
 */

import type {
  PaymentState,
  PaymentEvent,
  AuditEntry,
  Payment,
  Clock,
} from "./types.js";

// ---------------------------------------------------------------------------
// Outcome types
// ---------------------------------------------------------------------------

/** The state machine moved the payment to a new state. */
interface MoveOutcome {
  kind: "MOVE";
  toState: PaymentState;
  auditReason?: string;
}

/** No state change; log the event and move on. */
interface NoopOutcome {
  kind: "NOOP";
  auditReason?: string;
}

/** Stay in MANUAL_REVIEW and attach the event as evidence. */
interface HoldOutcome {
  kind: "HOLD";
  auditReason: string;
}

/** Move to MANUAL_REVIEW and fire an alert. */
interface ManualReviewOutcome {
  kind: "MANUAL_REVIEW";
  auditReason: string;
}

/**
 * Runner bug: an event that should never arrive in this state.
 * Only thrown for runner-generated events; bank events never throw (they go to MANUAL_REVIEW).
 */
interface IllegalOutcome {
  kind: "ILLEGAL";
  reason: string;
}

type CellOutcome =
  | MoveOutcome
  | NoopOutcome
  | HoldOutcome
  | ManualReviewOutcome
  | IllegalOutcome;

// ---------------------------------------------------------------------------
// TransitionResult  -  returned to the caller
// ---------------------------------------------------------------------------

export type TransitionResultKind =
  | "MOVED"        // state changed
  | "NOOP"         // no change, logged
  | "HOLD"         // stayed in MANUAL_REVIEW, evidence attached
  | "MANUAL_REVIEW" // escalated to MANUAL_REVIEW
  | "ILLEGAL";     // runner bug, threw

export interface TransitionResult {
  kind: TransitionResultKind;
  fromState: PaymentState;
  toState: PaymentState;
  auditEntry: AuditEntry;
  /** True if an operator alert should be fired (MR! cells). */
  alert: boolean;
}

// ---------------------------------------------------------------------------
// Transition table
// ---------------------------------------------------------------------------
// Key: `${state}:${eventType}`
// ---------------------------------------------------------------------------

type TableKey = `${PaymentState}:${PaymentEvent["type"]}`;

const ILLEGAL = (reason: string): IllegalOutcome => ({ kind: "ILLEGAL", reason });
const MOVE = (toState: PaymentState, auditReason?: string): MoveOutcome =>
  auditReason !== undefined ? { kind: "MOVE", toState, auditReason } : { kind: "MOVE", toState };
const NOOP = (auditReason?: string): NoopOutcome =>
  auditReason !== undefined ? { kind: "NOOP", auditReason } : { kind: "NOOP" };
const HOLD = (auditReason: string): HoldOutcome => ({ kind: "HOLD", auditReason });
const MR = (auditReason: string): ManualReviewOutcome => ({ kind: "MANUAL_REVIEW", auditReason });

const TABLE: Record<TableKey, CellOutcome> = {
  // -------------------------------------------------------------------------
  // SEND_INTENT_RECORDED
  // -------------------------------------------------------------------------
  "CREATED:SEND_INTENT_RECORDED":      MOVE("SENDING"),
  "SENDING:SEND_INTENT_RECORDED":      ILLEGAL("SEND_INTENT_RECORDED in SENDING"),
  "UNKNOWN:SEND_INTENT_RECORDED":      ILLEGAL("SEND_INTENT_RECORDED in UNKNOWN"),
  "CONFIRMED:SEND_INTENT_RECORDED":    ILLEGAL("SEND_INTENT_RECORDED in CONFIRMED"),
  "FAILED:SEND_INTENT_RECORDED":       ILLEGAL("SEND_INTENT_RECORDED in FAILED"),
  "MANUAL_REVIEW:SEND_INTENT_RECORDED":ILLEGAL("SEND_INTENT_RECORDED in MANUAL_REVIEW"),

  // -------------------------------------------------------------------------
  // BANK_ACCEPTED (sync)
  // -------------------------------------------------------------------------
  "CREATED:BANK_ACCEPTED":             ILLEGAL("BANK_ACCEPTED in CREATED"),
  "SENDING:BANK_ACCEPTED":             MOVE("CONFIRMED"),
  "UNKNOWN:BANK_ACCEPTED":             ILLEGAL("late sync BANK_ACCEPTED in UNKNOWN  -  must arrive as ASYNC_CONFIRM"),
  "CONFIRMED:BANK_ACCEPTED":           ILLEGAL("BANK_ACCEPTED in CONFIRMED"),
  "FAILED:BANK_ACCEPTED":              ILLEGAL("BANK_ACCEPTED in FAILED"),
  "MANUAL_REVIEW:BANK_ACCEPTED":       ILLEGAL("BANK_ACCEPTED in MANUAL_REVIEW"),

  // -------------------------------------------------------------------------
  // BANK_REJECTED_PERMANENT
  // -------------------------------------------------------------------------
  "CREATED:BANK_REJECTED_PERMANENT":        ILLEGAL("BANK_REJECTED_PERMANENT in CREATED"),
  "SENDING:BANK_REJECTED_PERMANENT":        MOVE("FAILED"),
  "UNKNOWN:BANK_REJECTED_PERMANENT":        ILLEGAL("BANK_REJECTED_PERMANENT in UNKNOWN"),
  "CONFIRMED:BANK_REJECTED_PERMANENT":      ILLEGAL("BANK_REJECTED_PERMANENT in CONFIRMED"),
  "FAILED:BANK_REJECTED_PERMANENT":         ILLEGAL("BANK_REJECTED_PERMANENT in FAILED"),
  "MANUAL_REVIEW:BANK_REJECTED_PERMANENT":  ILLEGAL("BANK_REJECTED_PERMANENT in MANUAL_REVIEW"),

  // -------------------------------------------------------------------------
  // BANK_REJECTED_TRANSIENT
  // Runner checks retry count BEFORE calling applyEvent:
  //   - if retries < max  -> sends BANK_REJECTED_TRANSIENT  -> stays SENDING (runner retries)
  //   - if retries >= max -> sends TRANSIENT_RETRIES_EXHAUSTED -> moves to FAILED
  // -------------------------------------------------------------------------
  "CREATED:BANK_REJECTED_TRANSIENT":        ILLEGAL("BANK_REJECTED_TRANSIENT in CREATED"),
  "SENDING:BANK_REJECTED_TRANSIENT":        MOVE("SENDING", "transient rejection  -  stay SENDING, runner will retry"),
  "UNKNOWN:BANK_REJECTED_TRANSIENT":        ILLEGAL("BANK_REJECTED_TRANSIENT in UNKNOWN"),
  "CONFIRMED:BANK_REJECTED_TRANSIENT":      ILLEGAL("BANK_REJECTED_TRANSIENT in CONFIRMED"),
  "FAILED:BANK_REJECTED_TRANSIENT":         ILLEGAL("BANK_REJECTED_TRANSIENT in FAILED"),
  "MANUAL_REVIEW:BANK_REJECTED_TRANSIENT":  ILLEGAL("BANK_REJECTED_TRANSIENT in MANUAL_REVIEW"),

  // -------------------------------------------------------------------------
  // TRANSIENT_RETRIES_EXHAUSTED (runner emits this when max retries reached)
  // -------------------------------------------------------------------------
  "CREATED:TRANSIENT_RETRIES_EXHAUSTED":        ILLEGAL("TRANSIENT_RETRIES_EXHAUSTED in CREATED"),
  "SENDING:TRANSIENT_RETRIES_EXHAUSTED":        MOVE("FAILED"),
  "UNKNOWN:TRANSIENT_RETRIES_EXHAUSTED":        ILLEGAL("TRANSIENT_RETRIES_EXHAUSTED in UNKNOWN"),
  "CONFIRMED:TRANSIENT_RETRIES_EXHAUSTED":      ILLEGAL("TRANSIENT_RETRIES_EXHAUSTED in CONFIRMED"),
  "FAILED:TRANSIENT_RETRIES_EXHAUSTED":         ILLEGAL("TRANSIENT_RETRIES_EXHAUSTED in FAILED"),
  "MANUAL_REVIEW:TRANSIENT_RETRIES_EXHAUSTED":  ILLEGAL("TRANSIENT_RETRIES_EXHAUSTED in MANUAL_REVIEW"),

  // -------------------------------------------------------------------------
  // STATUS_NOT_FOUND_IN_WINDOW (runner emits this when NOT_FOUND inside settle window)
  // Maps UNKNOWN->UNKNOWN (stay, wait for bank to settle)
  // -------------------------------------------------------------------------
  "CREATED:STATUS_NOT_FOUND_IN_WINDOW":        ILLEGAL("STATUS_NOT_FOUND_IN_WINDOW in CREATED"),
  "SENDING:STATUS_NOT_FOUND_IN_WINDOW":        ILLEGAL("STATUS_NOT_FOUND_IN_WINDOW in SENDING"),
  "UNKNOWN:STATUS_NOT_FOUND_IN_WINDOW":        MOVE("UNKNOWN", "NOT_FOUND inside settle window  -  wait"),
  "CONFIRMED:STATUS_NOT_FOUND_IN_WINDOW":      ILLEGAL("STATUS_NOT_FOUND_IN_WINDOW in CONFIRMED"),
  "FAILED:STATUS_NOT_FOUND_IN_WINDOW":         ILLEGAL("STATUS_NOT_FOUND_IN_WINDOW in FAILED"),
  "MANUAL_REVIEW:STATUS_NOT_FOUND_IN_WINDOW":  ILLEGAL("STATUS_NOT_FOUND_IN_WINDOW in MANUAL_REVIEW"),

  // -------------------------------------------------------------------------
  // BANK_TIMEOUT
  // -------------------------------------------------------------------------
  "CREATED:BANK_TIMEOUT":             ILLEGAL("BANK_TIMEOUT in CREATED"),
  "SENDING:BANK_TIMEOUT":             MOVE("UNKNOWN"),
  "UNKNOWN:BANK_TIMEOUT":             MOVE("UNKNOWN", "status check timed out  -  stay UNKNOWN, counts as a check"),
  "CONFIRMED:BANK_TIMEOUT":           ILLEGAL("BANK_TIMEOUT in CONFIRMED"),
  "FAILED:BANK_TIMEOUT":              ILLEGAL("BANK_TIMEOUT in FAILED"),
  "MANUAL_REVIEW:BANK_TIMEOUT":       ILLEGAL("BANK_TIMEOUT in MANUAL_REVIEW"),

  // -------------------------------------------------------------------------
  // STATUS_CONFIRMED
  // -------------------------------------------------------------------------
  "CREATED:STATUS_CONFIRMED":         ILLEGAL("STATUS_CONFIRMED in CREATED"),
  "SENDING:STATUS_CONFIRMED":         MOVE("CONFIRMED", "status check recovery path"),
  "UNKNOWN:STATUS_CONFIRMED":         MOVE("CONFIRMED"),
  "CONFIRMED:STATUS_CONFIRMED":       NOOP("duplicate STATUS_CONFIRMED  -  already CONFIRMED"),
  "FAILED:STATUS_CONFIRMED":          MR("STATUS_CONFIRMED on FAILED  -  contradiction, investigate"),
  "MANUAL_REVIEW:STATUS_CONFIRMED":   HOLD("STATUS_CONFIRMED while in MANUAL_REVIEW  -  attached as evidence"),

  // -------------------------------------------------------------------------
  // STATUS_FAILED
  // -------------------------------------------------------------------------
  "CREATED:STATUS_FAILED":            ILLEGAL("STATUS_FAILED in CREATED"),
  "SENDING:STATUS_FAILED":            MOVE("FAILED", "status check recovery path"),
  "UNKNOWN:STATUS_FAILED":            MOVE("FAILED"),
  "CONFIRMED:STATUS_FAILED":          MR("STATUS_FAILED on CONFIRMED  -  contradiction, investigate"),
  "FAILED:STATUS_FAILED":             NOOP("duplicate STATUS_FAILED  -  already FAILED"),
  "MANUAL_REVIEW:STATUS_FAILED":      HOLD("STATUS_FAILED while in MANUAL_REVIEW  -  attached as evidence"),

  // -------------------------------------------------------------------------
  // STATUS_NOT_FOUND
  // Runner resolves settle window BEFORE calling applyEvent:
  //   SENDING inside window   -> STATUS_NOT_FOUND -> UNKNOWN (wait)
  //   SENDING outside window  -> runner resends; this event is not fired
  //   UNKNOWN inside window   -> STATUS_NOT_FOUND -> stay UNKNOWN
  //   UNKNOWN outside window  -> STATUS_NOT_FOUND -> SENDING (resend same key)
  // -------------------------------------------------------------------------
  "CREATED:STATUS_NOT_FOUND":         ILLEGAL("STATUS_NOT_FOUND in CREATED"),
  "SENDING:STATUS_NOT_FOUND":         MOVE("UNKNOWN", "inside settle window  -  wait for bank"),
  "UNKNOWN:STATUS_NOT_FOUND":         MOVE("SENDING", "outside settle window  -  resend same key"),
  "CONFIRMED:STATUS_NOT_FOUND":       MR("STATUS_NOT_FOUND on CONFIRMED  -  contradiction, investigate"),
  "FAILED:STATUS_NOT_FOUND":          NOOP("STATUS_NOT_FOUND on FAILED  -  already terminal"),
  "MANUAL_REVIEW:STATUS_NOT_FOUND":   HOLD("STATUS_NOT_FOUND while in MANUAL_REVIEW  -  attached as evidence"),

  // -------------------------------------------------------------------------
  // ASYNC_CONFIRM
  // -------------------------------------------------------------------------
  "CREATED:ASYNC_CONFIRM":            MR("ASYNC_CONFIRM on CREATED  -  bank confirms a payment we never sent"),
  "SENDING:ASYNC_CONFIRM":            MOVE("CONFIRMED"),
  "UNKNOWN:ASYNC_CONFIRM":            MOVE("CONFIRMED"),
  "CONFIRMED:ASYNC_CONFIRM":          NOOP("duplicate ASYNC_CONFIRM  -  already CONFIRMED"),
  "FAILED:ASYNC_CONFIRM":             MR("ASYNC_CONFIRM on FAILED  -  contradiction, investigate"),
  "MANUAL_REVIEW:ASYNC_CONFIRM":      HOLD("ASYNC_CONFIRM while in MANUAL_REVIEW  -  attached as evidence"),

  // -------------------------------------------------------------------------
  // ASYNC_FAILURE
  // -------------------------------------------------------------------------
  "CREATED:ASYNC_FAILURE":            MR("ASYNC_FAILURE on CREATED  -  bank reports failure for a payment we never sent"),
  "SENDING:ASYNC_FAILURE":            MOVE("FAILED"),
  "UNKNOWN:ASYNC_FAILURE":            MOVE("FAILED"),
  "CONFIRMED:ASYNC_FAILURE":          MR("ASYNC_FAILURE on CONFIRMED  -  contradiction, investigate"),
  "FAILED:ASYNC_FAILURE":             NOOP("duplicate ASYNC_FAILURE  -  already FAILED"),
  "MANUAL_REVIEW:ASYNC_FAILURE":      HOLD("ASYNC_FAILURE while in MANUAL_REVIEW  -  attached as evidence"),

  // -------------------------------------------------------------------------
  // CHECKS_EXHAUSTED
  // -------------------------------------------------------------------------
  "CREATED:CHECKS_EXHAUSTED":         ILLEGAL("CHECKS_EXHAUSTED in CREATED"),
  "SENDING:CHECKS_EXHAUSTED":         ILLEGAL("CHECKS_EXHAUSTED in SENDING"),
  "UNKNOWN:CHECKS_EXHAUSTED":         MOVE("MANUAL_REVIEW"),
  "CONFIRMED:CHECKS_EXHAUSTED":       ILLEGAL("CHECKS_EXHAUSTED in CONFIRMED"),
  "FAILED:CHECKS_EXHAUSTED":          ILLEGAL("CHECKS_EXHAUSTED in FAILED"),
  "MANUAL_REVIEW:CHECKS_EXHAUSTED":   ILLEGAL("CHECKS_EXHAUSTED in MANUAL_REVIEW"),

  // -------------------------------------------------------------------------
  // RECOVERY_ON_RESTART
  // -------------------------------------------------------------------------
  "CREATED:RECOVERY_ON_RESTART":      MOVE("SENDING", "restart recovery: record intent then send"),
  "SENDING:RECOVERY_ON_RESTART":      MOVE("SENDING", "restart recovery: status check, never blind resend"),
  "UNKNOWN:RECOVERY_ON_RESTART":      MOVE("UNKNOWN", "restart recovery: continue status checks, count preserved"),
  "CONFIRMED:RECOVERY_ON_RESTART":    NOOP("restart recovery: already CONFIRMED"),
  "FAILED:RECOVERY_ON_RESTART":       NOOP("restart recovery: already FAILED"),
  "MANUAL_REVIEW:RECOVERY_ON_RESTART":NOOP("restart recovery: already in MANUAL_REVIEW"),
};

// ---------------------------------------------------------------------------
// applyEvent
// ---------------------------------------------------------------------------

export class IllegalTransitionError extends Error {
  constructor(
    public readonly state: PaymentState,
    public readonly event: PaymentEvent["type"],
    reason: string,
  ) {
    super(`Illegal transition: ${event} in ${state}  -  ${reason}`);
    this.name = "IllegalTransitionError";
  }
}

export function applyEvent(
  payment: Payment,
  event: PaymentEvent,
  clock: Clock,
): TransitionResult {
  const key: TableKey = `${payment.state}:${event.type}`;
  const cell = TABLE[key];

  if (!cell) {
    // Should never happen if TABLE is complete; treat as ILLEGAL.
    throw new IllegalTransitionError(
      payment.state,
      event.type,
      "no cell in transition table",
    );
  }

  const reason =
    "reason" in event ? event.reason :
    "auditReason" in cell ? cell.auditReason :
    undefined;

  if (cell.kind === "ILLEGAL") {
    throw new IllegalTransitionError(payment.state, event.type, cell.reason);
  }

  let toState: PaymentState;
  let resultKind: TransitionResultKind;
  let alert = false;

  switch (cell.kind) {
    case "MOVE":
      toState = cell.toState;
      resultKind = "MOVED";
      break;
    case "NOOP":
      toState = payment.state;
      resultKind = "NOOP";
      break;
    case "HOLD":
      toState = "MANUAL_REVIEW";
      resultKind = "HOLD";
      break;
    case "MANUAL_REVIEW":
      toState = "MANUAL_REVIEW";
      resultKind = "MANUAL_REVIEW";
      alert = true;
      break;
  }

  const auditEntry: AuditEntry = {
    paymentId: payment.id,
    distributionId: payment.distributionId,
    investorId: payment.investorId,
    event: event.type,
    fromState: payment.state,
    toState,
    timestamp: clock.now(),
    ...(reason !== undefined ? { reason } : {}),
  };

  return {
    kind: resultKind,
    fromState: payment.state,
    toState,
    auditEntry,
    alert,
  };
}
